/**
 * @method
 * @name paymium#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://paymium.github.io/api-documentation/#tag/Transfer/operation/create-email-transfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Paymium) TransferAsync(code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) <-chan AsyncResult[TransferEntry] {
	ch := make(chan AsyncResult[TransferEntry], 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Paymium) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	if strings.Index(toAccount, "@") < 0 {
		panic(ExchangeError(this.Id + " transfer() only allows transfers to an email address"))
	}
	if (code != "BTC") && (code != "EUR") {
		panic(ExchangeError(this.Id + " transfer() only allows BTC or EUR"))
	}
	var request map[string]any = map[string]any{
		"currency": currency["id"],
		"amount":   this.CurrencyToPrecision(code, amount),
		"email":    toAccount,
	}

	r1 := <-this.PrivatePostUserEmailTransfers(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value

	//
	//     {
	//         "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
	//         "type": "Transfer",
	//         "currency": "BTC",
	//         "currency_amount": "string",
	//         "created_at": "2013-10-24T10:34:37.000Z",
	//         "updated_at": "2013-10-24T10:34:37.000Z",
	//         "amount": "1.0",
	//         "state": "executed",
	//         "currency_fee": "0.0",
	//         "btc_fee": "0.0",
	//         "comment": "string",
	//         "traded_btc": "string",
	//         "traded_currency": "string",
	//         "direction": "buy",
	//         "price": "string",
	//         "account_operations": [
	//             {
	//                 "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
	//                 "amount": "1.0",
	//                 "currency": "BTC",
	//                 "created_at": "2013-10-24T10:34:37.000Z",
	//                 "created_at_int": 1389094259,
	//                 "name": "account_operation",
	//                 "address": "1FPDBXNqSkZMsw1kSkkajcj8berxDQkUoc",
	//                 "tx_hash": "string",
	//                 "is_trading_account": true
	//             }
	//         ]
	//     }
	//
	ch <- AsyncResult[TransferEntry]{Value: this.ParseTransfer(response, currency)}
	return nil
}
func (this *Paymium) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	//     {
	//         "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
	//         "type": "Transfer",
	//         "currency": "BTC",
	//         "currency_amount": "string",
	//         "created_at": "2013-10-24T10:34:37.000Z",
	//         "updated_at": "2013-10-24T10:34:37.000Z",
	//         "amount": "1.0",
	//         "state": "executed",
	//         "currency_fee": "0.0",
	//         "btc_fee": "0.0",
	//         "comment": "string",
	//         "traded_btc": "string",
	//         "traded_currency": "string",
	//         "direction": "buy",
	//         "price": "string",
	//         "account_operations": [
	//             {
	//                 "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
	//                 "amount": "1.0",
	//                 "currency": "BTC",
	//                 "created_at": "2013-10-24T10:34:37.000Z",
	//                 "created_at_int": 1389094259,
	//                 "name": "account_operation",
	//                 "address": "1FPDBXNqSkZMsw1kSkkajcj8berxDQkUoc",
	//                 "tx_hash": "string",
	//                 "is_trading_account": true
	//             }
	//         ]
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var currencyId *string = this.SafeString(transfer, "currency")
	var updatedAt *string = this.SafeString(transfer, "updated_at")
	var timetstamp any = this.ParseDate(updatedAt)
	var accountOperations []any = SafeListTyped(transfer, "account_operations")
	var firstOperation map[string]any = SafeMapTyped(accountOperations, 0)
	var status *string = this.SafeString(transfer, "state")
	return TransferEntryFromMap(map[string]any{
		"info":        transfer,
		"id":          this.SafeString(transfer, "uuid"),
		"timestamp":   timetstamp,
		"datetime":    this.Iso8601(timetstamp),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"amount":      this.SafeNumber(transfer, "amount"),
		"fromAccount": nil,
		"toAccount":   this.SafeString(firstOperation, "address"),
		"status":      this.ParseTransferStatus(status),
	})
}
func (this *Paymium) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"executed": "ok",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Paymium) Nonce() int64 {
	// the venue accepts any strictly-increasing integer, so use milliseconds: with the second-resolution base nonce a burst of N calls would leave incrementingNonce N seconds ahead of the clock
	return this.Milliseconds()
}
func (this *Paymium) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var baseApiUrl *string = this.SafeString(this.Urls["api"], "rest")
	if baseApiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var baseUrl *string = baseApiUrl
	var url string = *baseUrl + "/" + this.Version + "/" + this.ImplodeParams(path, params)
	var query any = this.Omit(params, this.ExtractParams(path))
	queryMap, _ := query.(map[string]any)
	var hasQuery bool = (len(queryMap) > 0)
	if api[0] == "public" {
		if hasQuery {
			url += "?" + this.Urlencode(query)
		}
	} else {
		this.CheckRequiredCredentials()
		// paymium requires an increasing nonce
		var nonce string = strconv.FormatInt(this.IncrementingNonce(), 10)
		var auth string = nonce + url
		var signedHeaders map[string]any = map[string]any{
			"Api-Key":   this.ApiKey,
			"Api-Nonce": nonce,
		}
		var signedBody string = ""
		if (method == "POST") && hasQuery {
			signedBody = this.Json(query)
		}
		if method == "POST" {
			if hasQuery {
				auth += signedBody
				signedHeaders["Content-Type"] = "application/json"
			}
		} else {
			if hasQuery {
				var queryString string = this.Urlencode(query)
				auth = nonce + url + queryString
				url += "?" + queryString
			}
		}
		signedHeaders["Api-Signature"] = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256)
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    signedBody,
			"headers": signedHeaders,
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    nil,
		"headers": nil,
	}
}
func (this *Paymium) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if response == nil {
		return nil
	}
	var errors any = this.SafeValue(response, "errors")
	if errors != nil {
		panic(ExchangeError(this.Id + " " + this.Json(response)))
	}
	return nil
}

func NewPaymium(userConfig map[string]any) *Paymium {
	p := newPaymium()
	p.Init(userConfig)
	return p
}

func (this *Paymium) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

